function tokenizeWords(text) {
    const map = [];
    const regex = /\S+/g;
    let match;
    while ((match = regex.exec(text)) !== null) {
        map.push({
            text: match[0],
            start: match.index,
            end: match.index + match[0].length
        });
    }
    return map;
}

